input.sparql:
SELECT ?s ?class ?label ?t ?tclass ?tlabel WHERE {
  ?s a ?class .
  FILTER(contains(str(?class), "Electric"))
  ?s rdfs:label ?label .
  OPTIONAL { ?s ref:hasExternalReference ?t . ?t a ?tclass . ?t rdfs:label ?tlabel . }
}

SELECT ?p ?pclass ?label WHERE {
  ?p a ?pclass .
  FILTER(contains(LCASE(str(?pclass)), "electric"))
  OPTIONAL { ?p rdfs:label ?label . }
}

SELECT ?p ?class ?tsid WHERE {
  ?p ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?p rdfs:label ?label . }
}
